const cleanTag = (locale?: string | null) => locale?.trim().replace(/_/g, '-');

export function resolveScreenLanguage(locale?: string | null): 'en' | 'nl' {
  const primary = cleanTag(locale)?.split('-')[0]?.toLowerCase();
  return primary === 'nl' ? 'nl' : 'en';
}

export function screenFormatLocale(locale?: string | null): string {
  const tag = cleanTag(locale);
  const fallback = resolveScreenLanguage(tag) === 'nl' ? 'nl-NL' : 'en-GB';
  if (!tag || !/^(en|nl)-/i.test(tag)) return fallback;
  try {
    return Intl.getCanonicalLocales(tag)[0] ?? fallback;
  } catch {
    return fallback;
  }
}
